/**
 * The little of celebrations that Today needs as it first draws: whether
 * they are on, this device's state, the day, and the streak the chip last
 * drew. Everything else (the engine, the claim, the words) is loaded when
 * there is something to decide, so it stays off the first paint.
 */
import { dayIndex } from '@lexpad/core';
import { db, getMeta, setMeta, type StoredCelebrate } from '@/db/schema.js';
import { loadSrsView, type SrsView } from '@/features/schedule/data.js';
import { localTimeZone } from '@/lib/format.js';

/**
 * The `srs_v2` feature that switches celebrations off for everybody. On by
 * default, like `learnTips`: a server that never heard of it leaves it on,
 * and `celebrations: false` is the kill switch. Unlike the SRS v2 screens it
 * does not need SRS v2 itself, so a client the rollout has not reached
 * still celebrates.
 */
export const CELEBRATE_FEATURE = 'celebrations';

/** Whether celebrations run here at all. Off: the app is exactly as it was. */
export function celebrationsOn(view: SrsView): boolean {
  return view.features[CELEBRATE_FEATURE] !== false;
}

/** What a screen needs to know. */
export interface CelebrateView {
  /** The feature is on for this account and client. */
  on: boolean;
  /** This device's state, or null before the baseline is settled. */
  state: StoredCelebrate | null;
  /** The account's data has arrived at least once, so a baseline can be taken. */
  synced: boolean;
}

export const CELEBRATE_OFF: CelebrateView = { on: false, state: null, synced: false };

/** Reads the switch and this device's state. */
export async function loadCelebrate(): Promise<CelebrateView> {
  const srs = await loadSrsView();
  if (!celebrationsOn(srs)) return CELEBRATE_OFF;
  const [state, lastSync] = await Promise.all([getMeta('celebrate'), getMeta('lastSyncAt')]);
  return { on: true, state, synced: lastSync !== null };
}

/** Today's local day index. */
export function localDay(now: Date = new Date()): number {
  return dayIndex(now, localTimeZone());
}

/** Reads, changes and writes the state in one transaction; nothing before it is settled. */
export async function update(
  change: (state: StoredCelebrate) => StoredCelebrate | undefined,
): Promise<StoredCelebrate | null> {
  return db.transaction('rw', db.meta, async () => {
    const state = await getMeta('celebrate');
    if (state === null) return null;
    const next = change(state);
    if (next !== undefined && next !== state) await setMeta('celebrate', next);
    return next ?? state;
  });
}

/** The streak the chip last drew. */
export async function noteChip(streak: number): Promise<void> {
  await update((state) => (state.chip === streak ? undefined : { ...state, chip: streak }));
}
