/**
 * The moment offer (marketing/research/2026-10-16-trial-model-and-moment-
 * offers.md §5, §6, §10; owner's go 16 Oct 2026): a personal price the
 * server gives at the first real moment the learner causes, once per
 * account ever, open 72 hours from when it is first shown.
 *
 * The server decides everything (`POST /billing/moment`); this file only
 * says which moment a screen is, whether this client may ask at all, and
 * the caps the app keeps on this device. Pure, so every rule has a test.
 *
 * - The iPhone app never asks (and the server refuses it there): nothing
 *   is spent on a device that cannot sell the offer, and the offer is never
 *   mentioned there.
 * - The AI-limit line is information on every hit; the price is mentioned
 *   on it at most once a day (`inlineMentionDue`). Never a pop-up.
 * - The card after a milestone is on the next visit to Today, never in the
 *   celebration, at most one every `MOMENT_MILESTONE_EVERY_DAYS`, once per
 *   milestone kind.
 */
import type { ApiBillingState, ApiMomentKind } from '@/api/types.js';
import type { StoredOfferNotes } from '@/db/schema.js';
import { bonusDays, bonusPeriod, type Offer } from './offer.js';
import type { Occasion } from './ProOffer.js';
import { t } from '@/i18n/index.js';

const HOUR = 3_600_000;
const DAY = 24 * HOUR;

/** The offer family the server marks as given at a moment (`copyKey`). */
export const MOMENT_COPY_KEY = 'moment';

export function isMomentOffer(offer: Offer | undefined): boolean {
  return offer?.copyKey === MOMENT_COPY_KEY;
}

/**
 * The moment offer's title: "Just for you: 2 months of Pro free" for a
 * bonus (the price is the plan's own, so the days are what is new), else
 * "Just for you: Pro for $24.99 for your first year".
 */
export function momentTitle(offer: Offer, first: string): string {
  const bonus = bonusDays(offer);
  return bonus > 0
    ? t('moment.bonus.title', { period: bonusPeriod(bonus) })
    : t('moment.banner.title', { amount: first });
}

/** The moment offer's head on the plans, the price and what follows together. */
export function momentLead(offer: Offer | undefined, first: string, renewal: string): string {
  const bonus = bonusDays(offer);
  return bonus > 0
    ? t('moment.bonus.justForYou', { first, period: bonusPeriod(bonus), days: bonus, renewal })
    : t('moment.justForYou', { first, renewal });
}

/** The AI-limit line's one mention of the open moment offer. */
export function momentInline(offer: Offer, first: string, until: string): string {
  const bonus = bonusDays(offer);
  return bonus > 0
    ? t('moment.bonus.inline', { amount: first, period: bonusPeriod(bonus), until })
    : t('moment.inline', { amount: first, until });
}

/**
 * Which moment an offer sheet is, by where it was opened (§5): the AI cards
 * used up, a Pro feature tapped, the plan opened from Settings. The AI
 * screen before anything was asked (`aiIdle`) is not a moment: nobody was
 * stopped by anything there.
 */
export function momentKindFor(occasion: Occasion): ApiMomentKind | undefined {
  switch (occasion) {
    case 'resting':
      return 'ai_limit';
    case 'settings':
      return 'plan_page';
    case 'lex':
    case 'sayIt':
    case 'sentence':
    case 'voice':
    case 'readText':
    case 'notebook':
      return 'pro_feature';
    case 'aiIdle':
      return undefined;
  }
}

/**
 * Whether this client may tell the server about a moment: never in the
 * iPhone app, never without a way to buy here, never on Pro (a payer, a
 * trial, days given), never while another offer is open (the early price
 * wins), and not again once a moment offer is in hand.
 */
export function momentAskable(
  state: ApiBillingState | null,
  where: { ios: boolean; sells: boolean; openOffer: Offer | undefined },
): boolean {
  if (state === null || where.ios || !where.sells) return false;
  if (state.plan === 'pro') return false;
  return where.openOffer === undefined;
}

/**
 * The device's time zone as a reader names it ("Berlin"), only when it is
 * not the account's own (§10.1: the app says its own clock without a name,
 * and names it only when the two differ). Undefined when they agree or
 * either is unknown.
 */
export function zoneNameIfOther(accountZone: string | undefined, deviceZone?: string): string | undefined {
  let device = deviceZone;
  if (device === undefined) {
    try {
      device = Intl.DateTimeFormat().resolvedOptions().timeZone;
    } catch {
      return undefined;
    }
  }
  if (accountZone === undefined || accountZone === '' || device === '' || accountZone === device) {
    return undefined;
  }
  if (device === 'UTC' || device === 'Etc/UTC') return 'UTC';
  const city = device.slice(device.lastIndexOf('/') + 1);
  return city.replaceAll('_', ' ');
}

/** A local calendar day as a number: the day the inline mention was made. */
export function localDayNumber(at: Date): number {
  return Math.floor((at.getTime() - at.getTimezoneOffset() * 60_000) / DAY);
}

/** Whether the AI-limit line may mention the open moment offer now: once a day (§5 M3). */
export function inlineMentionDue(notes: StoredOfferNotes, now: Date): boolean {
  return notes.momentInlineDay !== localDayNumber(now);
}

/** The offer the AI-limit line mentioned in this run of the app: it stays for the run. */
let inlineHeldId: string | undefined;

export function inlineHeld(): string | undefined {
  return inlineHeldId;
}

export function holdInline(offerId: string): void {
  inlineHeldId = offerId;
}

/** For tests: a new run of the app. */
export function forgetMomentInline(): void {
  inlineHeldId = undefined;
}

/** The notes once the AI-limit line mentioned the offer today. */
export function noteInlineMention(notes: StoredOfferNotes, now: Date): StoredOfferNotes {
  return { ...notes, momentInlineDay: localDayNumber(now) };
}

// ---------------------------------------------------------------------------
// The card after a milestone (§5 M6)

/** At most one card after a milestone this often (§5 M6). */
export const MOMENT_MILESTONE_EVERY_DAYS = 30;
/** How fresh the milestone must be: the next visit to Today, within the day. */
export const MOMENT_MILESTONE_FRESH_HOURS = 24;
/** No card in an account's first days (the general rule of §5). */
export const MOMENT_QUIET_DAYS = 2;

/**
 * The milestones the card speaks of (§5 M6: a 7, 30 or 100 day streak, the
 * first mastered word, a words milestone), by the celebration's own id.
 */
export const MOMENT_MILESTONES = ['streak7', 'streakBig', 'firstMastered', 'words'] as const;
export type MomentMilestone = (typeof MOMENT_MILESTONES)[number];

/** The milestone the next visit may speak of, from the notes; undefined when none is fresh. */
export function freshMilestone(
  notes: StoredOfferNotes,
  now: Date,
): { id: MomentMilestone; count: number | undefined; key: string } | undefined {
  const id = notes.milestoneId;
  if (id === undefined || !(MOMENT_MILESTONES as readonly string[]).includes(id)) return undefined;
  const at = notes.milestoneAt === undefined ? Number.NaN : Date.parse(notes.milestoneAt);
  if (Number.isNaN(at)) return undefined;
  const since = now.getTime() - at;
  if (since < 0 || since > MOMENT_MILESTONE_FRESH_HOURS * HOUR) return undefined;
  // A milestone said with its number needs the number: never a guessed one.
  const count = id === 'streak7' ? 7 : notes.milestoneCount;
  if ((id === 'streakBig' || id === 'words') && count === undefined) return undefined;
  return {
    id: id as MomentMilestone,
    count,
    key: count === undefined ? id : `${id}:${String(count)}`,
  };
}

export interface MomentMilestoneSignals {
  now: Date;
  /** When the account was made; unknown reads as too new. */
  createdAt: Date | undefined;
  notes: StoredOfferNotes;
  /** This client may sell (never the iPhone app for this). */
  sells: boolean;
  ios: boolean;
  /** The open offer, if any. */
  offer: Offer | undefined;
}

/**
 * Whether Today shows the card after a milestone: a Free learner after the
 * trial, on a client that can sell, who did not say "Don't remind me",
 * with no other offer open, a fresh milestone of a kind not spoken of
 * before, and no such card in the last `MOMENT_MILESTONE_EVERY_DAYS`.
 */
export function momentMilestoneShows(state: ApiBillingState | null, s: MomentMilestoneSignals): boolean {
  if (state === null || state.plan === 'pro' || state.trialEnded === undefined) return false;
  if (state.offerReminders === false || !s.sells || s.ios) return false;
  if (s.offer !== undefined && !isMomentOffer(s.offer)) return false;
  if (s.createdAt === undefined || s.now.getTime() - s.createdAt.getTime() < MOMENT_QUIET_DAYS * DAY) {
    return false;
  }
  const milestone = freshMilestone(s.notes, s.now);
  if (milestone === undefined) return false;
  if (s.notes.momentMilestoneKinds?.includes(milestone.key) === true) return false;
  const last = s.notes.momentMilestoneAt === undefined ? Number.NaN : Date.parse(s.notes.momentMilestoneAt);
  return Number.isNaN(last) || s.now.getTime() - last >= MOMENT_MILESTONE_EVERY_DAYS * DAY;
}

/** The notes once the card was put on screen: once per kind, one a month. */
export function noteMomentMilestone(notes: StoredOfferNotes, now: Date): StoredOfferNotes {
  const milestone = freshMilestone(notes, now);
  const kinds = notes.momentMilestoneKinds ?? [];
  return {
    ...notes,
    momentMilestoneAt: now.toISOString(),
    momentMilestoneKinds:
      milestone === undefined || kinds.includes(milestone.key) ? kinds : [...kinds, milestone.key],
  };
}

/** The milestone said back, from the celebration's own id and number. */
export function milestoneWords(
  milestone: MomentMilestone,
  count: number | undefined,
): { title: string; line: string } {
  // `freshMilestone` never names a streak or a words milestone without its number.
  switch (milestone) {
    case 'streak7':
    case 'streakBig':
      return {
        title: t('moment.milestone.streakTitle', { count: count ?? 0 }),
        line: t('moment.milestone.streakLine'),
      };
    case 'firstMastered':
      return { title: t('moment.milestone.masteredTitle'), line: t('moment.milestone.masteredLine') };
    case 'words':
      return {
        title: t('moment.milestone.wordsTitle', { count: count ?? 0 }),
        line: t('moment.milestone.wordsLine'),
      };
  }
}
