/**
 * Why a purchase failed, kept and told.
 *
 * A purchase in the iPhone or Android app can fail inside the device
 * (StoreKit, Google Play, the shell) before any billing endpoint is called.
 * The learner then sees "Something went wrong", which is right for them, but
 * without this the server's log shows nothing at all and the failure cannot
 * be told from any other. So each failure is written to the console with
 * what the store said, and sent to `POST /billing/purchase-problems`: the
 * step, the store's code and its error text. No token, signature or receipt
 * is ever part of it.
 */
import { billing as billingApi } from '@/api/endpoints.js';
import { ApiError } from '@/api/errors.js';
import type { ApiPurchaseProblem } from '@/api/types.js';
import { platform } from '@/lib/platform/index.js';
import { noteTrouble } from '@/features/review/review.js';

export type PurchaseStage = ApiPurchaseProblem['stage'];

/** A purchase step that failed, with what the store or the server said. */
export class PurchaseProblem extends Error {
  readonly stage: PurchaseStage;
  /** The plugin's or the server's code: `failed`, `no_app_transaction`, `offer_unsupported`. */
  readonly code: string;
  /** The store's own words (domain, code, description), when it gave any. */
  readonly detail: string | undefined;

  constructor(stage: PurchaseStage, code: string, detail?: string, options?: { cause?: unknown }) {
    // The message is the code, so a caller that only reads `message` still
    // tells one failure from another.
    super(code, options);
    this.name = 'PurchaseProblem';
    this.stage = stage;
    this.code = code;
    this.detail = detail;
  }
}

/** What a rejected Capacitor plugin call carries: `code`, and `data` the shell attached. */
interface PluginFailure {
  code?: unknown;
  message?: unknown;
  data?: { detail?: unknown } | null;
}

/** A store plugin's rejection as a problem at `stage`, keeping its code and its words. */
export function fromPlugin(stage: PurchaseStage, cause: unknown, fallback = 'failed'): PurchaseProblem {
  const failure = (cause ?? {}) as PluginFailure;
  const code = typeof failure.code === 'string' && failure.code !== '' ? failure.code : fallback;
  const detail =
    typeof failure.data?.detail === 'string' && failure.data.detail !== ''
      ? failure.data.detail
      : typeof failure.message === 'string' && failure.message !== ''
        ? failure.message
        : undefined;
  return new PurchaseProblem(stage, code, detail, { cause });
}

/** Whether a plugin rejection is somebody backing out of an Apple sheet. */
export function cancelledByPerson(cause: unknown): boolean {
  return (cause as { code?: unknown } | null)?.code === 'cancelled';
}

const CODE = /^[A-Za-z0-9_.-]{1,64}$/;
const VERSION = /^[0-9A-Za-z.+-]{1,32}$/;
const DETAIL_MAX = 300;

/** The report for one failure, or undefined for one that is not worth sending. */
export function describeProblem(
  cause: unknown,
  context: { stage: PurchaseStage; plan?: ApiPurchaseProblem['plan']; offerId?: string | undefined },
): ApiPurchaseProblem | undefined {
  // No network: the report could not arrive either, and the screen already says why.
  if (cause instanceof ApiError && cause.kind === 'offline') return undefined;
  let stage = context.stage;
  let code = 'unknown';
  let detail: string | undefined;
  if (cause instanceof PurchaseProblem) {
    ({ stage, code, detail } = cause);
  } else if (cause instanceof ApiError) {
    code = cause.code ?? cause.kind;
    detail = `${String(cause.status)} ${cause.message}`;
  } else if (cause instanceof Error) {
    code = cause.message;
  }
  const report: ApiPurchaseProblem = { stage, code: CODE.test(code) ? code : 'unknown' };
  if (detail !== undefined && detail !== '') report.detail = detail.slice(0, DETAIL_MAX);
  if (context.plan !== undefined) report.plan = context.plan;
  if (context.offerId !== undefined) report.offerId = context.offerId;
  const version = platform.env.appVersion;
  if (VERSION.test(version)) report.appVersion = version;
  return report;
}

/**
 * Writes the failure to the console, with the cause itself, and sends it to
 * the server. Fire and forget: a report that cannot be sent changes nothing
 * for the learner.
 */
export function reportPurchaseProblem(
  cause: unknown,
  context: { stage: PurchaseStage; plan?: ApiPurchaseProblem['plan']; offerId?: string | undefined },
): void {
  const report = describeProblem(cause, context);
  console.error('[purchase] failed', report ?? context, cause);
  if (report === undefined) return;
  // A purchase that failed is not a day to ask for a rating.
  noteTrouble();
  billingApi.reportPurchaseProblem(report).catch(() => undefined);
}
