/**
 * The Pro trial, as Today and Settings speak of it
 * (`marketing/research/2026-10-free-vs-pro.md`, section 5).
 *
 * Every new account is given Pro for a while, with no card, and then falls
 * back to Free with nothing taken away. The server decides all of it: it
 * grants the trial, says until when (`trial.endsAt`) while it runs, and says
 * that it ended (`trialEnded`) afterwards. This file only decides which of
 * three small moments Today shows, and when:
 *
 * - **midway**: from the third day (a 7-day trial's second), with a few
 *   words written, one card saying Pro is here until a date, and one thing
 *   to try with it;
 * - **ending**: in the last days (three, or a 7-day trial's two), one line in the hero saying when it ends
 *   and that nothing is charged;
 * - **ended**: the first visit after the end, one card saying what stays.
 *
 * Each is shown once (meta `trialNotes`), never in the first day of an
 * account, and only where Pro may be spoken of at all — the same silences
 * as `ProOffer`: a client that may not sell, no price, and a notebook in a
 * language Lexpad never charges for all hear nothing. Pure: the screen
 * passes the plan, the clock and what this device remembers.
 */
import type { ApiBillingState } from '@/api/types.js';
import type { StoredTrialNotes } from '@/db/schema.js';
import { canBuyHere, cheapestPrice, freeNotebook } from './state.js';

const HOUR_MS = 3_600_000;
const DAY_MS = 24 * HOUR_MS;

/**
 * Nothing about the trial in an account's first hours: the first day is for
 * the first words and the first practice (the new learner's journey). A
 * product rule for an in-app hint, not an allowance, so it lives here beside
 * the rule it shapes, like the other thresholds on Today.
 */
export const TRIAL_QUIET_HOURS = 24;

/**
 * The trial's length decides when its moments come (owner, 24 Oct 2026: new
 * accounts get 7 days of Pro, accounts that began with 14 keep them). A
 * trial of this many days or fewer is short: its cards come a day sooner
 * and its last days are fewer, so each still has room before the end.
 */
export const TRIAL_SHORT_MAX_DAYS = 7;

/** Days into the trial before the midway card (the marketer's "day 3 or later"). */
export const TRIAL_MIDWAY_AFTER_DAYS = 3;
/** The same for a short trial: day 2, after "Meet Lex" and before the midpoint. */
export const TRIAL_SHORT_MIDWAY_AFTER_DAYS = 2;

/**
 * Day of the trial for "Meet Lex" (trial-offers design §2.3: day 2; a short
 * trial's day 1, right after the quiet first day), and the words the account
 * needs first: something of its own for Lex to quiz.
 */
export const TRIAL_MEET_LEX_AFTER_DAYS = 2;
export const TRIAL_SHORT_MEET_LEX_AFTER_DAYS = 1;
export const TRIAL_MEET_LEX_MIN_WORDS = 3;

/**
 * "A week of Pro" comes at the trial's midpoint (§2.3: day 7 of 14): this
 * fraction of its length. For a 7-day trial it is the halfway card.
 */
export const TRIAL_HALF_AT = 0.5;

/** The midpoint that is a whole week in, and so may say "A week of Pro". */
export const TRIAL_WEEK_DAYS = 7;

/** Words in the account before the midway card: something of their own to try Pro with. */
export const TRIAL_MIDWAY_MIN_WORDS = 5;

/** Days before the end when the hero says when it ends (the same three days as the e-mail). */
export const TRIAL_ENDING_DAYS = 3;
/** The same for a short trial: its last two days. */
export const TRIAL_SHORT_ENDING_DAYS = 2;

/** When each of a trial's moments comes, in days from its start. */
export interface TrialSchedule {
  /** The trial's length in whole days. */
  days: number;
  meetLex: number;
  midway: number;
  /** The midpoint card ("A week of Pro" on a 14-day trial). */
  half: number;
  /** The hero's ending line shows in this many last days. */
  ending: number;
}

/** The moments' days for a trial of this many days. */
export function trialSchedule(days: number): TrialSchedule {
  const short = days <= TRIAL_SHORT_MAX_DAYS;
  return {
    days,
    meetLex: short ? TRIAL_SHORT_MEET_LEX_AFTER_DAYS : TRIAL_MEET_LEX_AFTER_DAYS,
    midway: short ? TRIAL_SHORT_MIDWAY_AFTER_DAYS : TRIAL_MIDWAY_AFTER_DAYS,
    half: days * TRIAL_HALF_AT,
    ending: short ? TRIAL_SHORT_ENDING_DAYS : TRIAL_ENDING_DAYS,
  };
}

/** Whether the midpoint is a week in, for "A week of Pro"; else it is the halfway card. */
export function halfIsWeek(schedule: TrialSchedule): boolean {
  return Math.round(schedule.half) === TRIAL_WEEK_DAYS;
}

/**
 * The trial's length in whole days, from its own start (the server's
 * `startedAt`, else `since`) to its end; undefined when neither is known.
 */
export function trialLength(endsAt: Date, start: Date | undefined): number | undefined {
  if (start === undefined) return undefined;
  const days = Math.round((endsAt.getTime() - start.getTime()) / DAY_MS);
  return days >= 1 ? days : undefined;
}

/** The running trial's schedule, from its own start; undefined when that is not known. */
export function runningSchedule(trial: RunningTrial, since: Date | undefined): TrialSchedule | undefined {
  const days = trialLength(trial.endsAt, trial.startedAt ?? since);
  return days === undefined ? undefined : trialSchedule(days);
}

/**
 * How long after the end its card may still appear. Somebody who bought
 * during the trial and whose plan lapsed months later has not "just" come
 * out of a trial, and a card telling them so would be a small lie.
 */
export const TRIAL_END_CARD_DAYS = 30;

/** A trial the server says is running, and still is by this clock. */
export interface RunningTrial {
  endsAt: Date;
  /** The server's `startedAt`, when it says. */
  startedAt: Date | undefined;
  /** The server's `endsAt`, as sent: what the notes remember it by. */
  key: string;
  lexQuestions: number;
  /** Today may show its day-by-day cards and hero line (the server's `touches`). */
  touches: boolean;
}

/** A trial the server says is over, while the account is on Free. */
export interface EndedTrial {
  endedAt: Date;
  key: string;
  lexQuestions: number;
  /** Today may show the end card (the server's `touches`). */
  touches: boolean;
}

function instant(iso: string | undefined): Date | undefined {
  if (iso === undefined) return undefined;
  const ms = Date.parse(iso);
  return Number.isNaN(ms) ? undefined : new Date(ms);
}

/** A count from the server, or zero for anything that is not a sensible one. */
function count(value: unknown): number {
  return typeof value === 'number' && Number.isFinite(value) && value > 0 ? Math.floor(value) : 0;
}

/**
 * The running trial, or undefined. A trial whose end has passed by this
 * device's clock is not running any more, whatever a copy of the plan read
 * before midnight still says: the server's next answer will say it ended.
 * An answer from a server that predates the trial has no `trial` at all.
 */
export function runningTrial(state: ApiBillingState | null, now: Date): RunningTrial | undefined {
  const trial = state?.trial;
  if (state === null || trial === undefined || state.plan !== 'pro') return undefined;
  const endsAt = instant(trial.endsAt);
  if (endsAt === undefined || endsAt.getTime() <= now.getTime()) return undefined;
  return {
    endsAt,
    startedAt: instant(trial.startedAt),
    key: trial.endsAt,
    lexQuestions: count(trial.lexQuestions),
    touches: trial.touches === true,
  };
}

/**
 * Whether the plan in hand still describes a trial that has run out by this
 * clock: the moment to read the plan again, once, so the end card can come.
 */
export function trialRanOut(state: ApiBillingState | null, now: Date): boolean {
  const endsAt = instant(state?.trial?.endsAt);
  return endsAt !== undefined && endsAt.getTime() <= now.getTime();
}

/** The trial that ended, while the account is on Free; undefined otherwise. */
export function endedTrial(state: ApiBillingState | null): EndedTrial | undefined {
  const ended = state?.trialEnded;
  if (state === null || ended === undefined || state.plan !== 'free') return undefined;
  const endedAt = instant(ended.endedAt);
  if (endedAt === undefined) return undefined;
  return {
    endedAt,
    key: ended.endedAt,
    lexQuestions: count(ended.lexQuestions),
    touches: ended.touches === true,
  };
}

/**
 * The trial's last day, as a date somebody reads: "Oct 22".
 *
 * `endsAt` is exclusive, so the date shown is the one of the last moment
 * that is still Pro. A trial that ends exactly at local midnight would
 * otherwise read "until Oct 23" and stop as Oct 23 begins. The year is
 * added only when it is not this one.
 */
export function trialDate(endsAt: Date, now: Date): string {
  const last = new Date(endsAt.getTime() - 1);
  const sameYear = last.getFullYear() === now.getFullYear();
  return last.toLocaleDateString(undefined, {
    month: 'short',
    day: 'numeric',
    ...(sameYear ? {} : { year: 'numeric' }),
  });
}

/**
 * Whether Today may speak of Pro at all, in this notebook, on this client:
 * the same silences as `ProOffer`, apart from the plan (a trial is Pro).
 * A client that may not sell shows nothing that leads to a price, there must
 * be a price, and a notebook Lexpad never charges for hears nothing.
 */
export function trialVoiced(
  state: ApiBillingState | null,
  targetLang: string | undefined,
  meaningLang: string | undefined,
): boolean {
  if (state === null || !canBuyHere(state) || cheapestPrice(state) === undefined) return false;
  return !freeNotebook(state, targetLang, meaningLang);
}

/** Which card Today shows about the trial. */
export type TrialCardKind = 'meetLex' | 'midway' | 'week' | 'ended';

/** Everything the choice needs, read by the screen. */
export interface TrialSignals {
  now: Date;
  /**
   * When the trial is taken to have started: the account's creation, or
   * failing that when this device first saw it running. Undefined until
   * either is known, and then nothing is shown.
   */
  since: Date | undefined;
  /** Words in the account. */
  words: number;
  /** What this device remembers. */
  notes: StoredTrialNotes;
  /** Moments already on screen in this run of the app, kept until put away. */
  held: ReadonlySet<TrialCardKind | 'ending'>;
  /** `trialVoiced` for the notebook in view. */
  voiced: boolean;
}

/** Whether the account is out of its first quiet hours. */
function pastQuiet(signals: TrialSignals): boolean {
  if (signals.since === undefined) return false;
  return signals.now.getTime() - signals.since.getTime() >= TRIAL_QUIET_HOURS * HOUR_MS;
}

/** Whether `now` is inside the trial's last days (two for a short trial, else three). */
function inEndingDays(trial: RunningTrial, signals: TrialSignals): boolean {
  const schedule = runningSchedule(trial, signals.since);
  const ending = schedule?.ending ?? TRIAL_ENDING_DAYS;
  return trial.endsAt.getTime() - signals.now.getTime() <= ending * DAY_MS;
}

/** Days since the trial began, by its own start (else the account's). */
function trialDay(trial: RunningTrial, signals: TrialSignals): number | undefined {
  const start = trial.startedAt ?? signals.since;
  if (start === undefined) return undefined;
  return (signals.now.getTime() - start.getTime()) / DAY_MS;
}

/** The notes' seen and done flags for one running-trial card. */
const RUNNING_NOTES = {
  meetLex: { seen: 'meetLexSeen', done: 'meetLexDone' },
  midway: { seen: 'midwaySeen', done: 'midwayDone' },
  week: { seen: 'weekSeen', done: 'weekDone' },
} as const;

type RunningCard = keyof typeof RUNNING_NOTES;

/**
 * The trial card for Today, or undefined. Whether the card's place is free
 * (one card on Today, one a session) is the slot's question, not this one.
 *
 * Only while the server says Today may speak (`touches`: its flag is on
 * and the learner has not said "Don't remind me"). In order of the trial's
 * days (trial-offers design §2.3), by the trial's own length
 * (`trialSchedule`): from its midpoint (day 7 of 14, day 3½ of 7) "A week
 * of Pro" or the halfway card, which offers Pro and is hidden for good by
 * any earlier "Not now"; from day 3 (a short trial's day 2) the midway
 * card; from day 2 (day 1) "Meet Lex" for somebody with a few words who
 * has not asked Lex anything. Each once; none in the last days (three, or
 * a short trial's two), whose line in the hero says it better.
 */
export function trialCard(state: ApiBillingState | null, signals: TrialSignals): TrialCardKind | undefined {
  if (!signals.voiced || !pastQuiet(signals)) return undefined;
  const { notes, held, now } = signals;

  const ended = endedTrial(state);
  if (ended !== undefined) {
    if (!ended.touches) return undefined;
    if (notes.endDone === ended.key) return undefined;
    if (notes.endSeen === ended.key) return held.has('ended') ? 'ended' : undefined;
    if (now.getTime() - ended.endedAt.getTime() > TRIAL_END_CARD_DAYS * DAY_MS) return undefined;
    return 'ended';
  }

  const running = runningTrial(state, now);
  if (!running?.touches) return undefined;
  // A card already on screen in this run stays until it is answered.
  for (const kind of Object.keys(RUNNING_NOTES) as RunningCard[]) {
    const keys = RUNNING_NOTES[kind];
    if (notes[keys.seen] === true && notes[keys.done] !== true) {
      if (held.has(kind)) return kind;
    }
  }
  if (inEndingDays(running, signals)) return undefined;
  const day = trialDay(running, signals);
  const schedule = runningSchedule(running, signals.since);
  if (day === undefined || schedule === undefined) return undefined;
  const fresh = (kind: RunningCard): boolean => notes[RUNNING_NOTES[kind].seen] !== true;

  if (day >= schedule.half) {
    // "Not now" on any card hides the next offer card (§2.3).
    return fresh('week') && notes.notNow !== true ? 'week' : undefined;
  }
  if (day >= schedule.midway && fresh('midway') && signals.words >= TRIAL_MIDWAY_MIN_WORDS) {
    return 'midway';
  }
  if (
    day >= schedule.meetLex &&
    fresh('meetLex') &&
    signals.words >= TRIAL_MEET_LEX_MIN_WORDS &&
    running.lexQuestions === 0
  ) {
    return 'meetLex';
  }
  return undefined;
}

/** Whether the hero says when the trial ends: once, in its last days. */
export function trialEndingLine(state: ApiBillingState | null, signals: TrialSignals): boolean {
  if (!signals.voiced || !pastQuiet(signals)) return false;
  const running = runningTrial(state, signals.now);
  if (running === undefined || !running.touches || !inEndingDays(running, signals)) return false;
  return signals.notes.endingSeen !== running.key || signals.held.has('ending');
}

/**
 * When the trial is taken to have started, for "day 3 or later": the
 * account's creation when it is known, which for a trial given at sign-up
 * is the start; otherwise the first time this device saw it running.
 */
export function trialSince(createdAt: string | undefined, notes: StoredTrialNotes): Date | undefined {
  return instant(createdAt) ?? instant(notes.firstSeen);
}

/**
 * Whether this build offers the trial to accounts that signed up without
 * one. The server keeps the opt-in closed (404) until its `pro_trial` flag
 * opens it to existing accounts, after the comparison weeks; the plan says
 * nothing about whether it is open to everybody, so a build switches the row
 * on with `VITE_TRIAL_OPT_IN=true` when the flag is opened, and a refusal
 * still hides it. The plan's `trialOffered` opens it for one account without
 * a build (TrialOptIn). Read on each call so a test can set it.
 */
export function trialOptInOn(): boolean {
  return import.meta.env.VITE_TRIAL_OPT_IN === 'true';
}

/**
 * Whether the trial opt-in is open to this account here: the build or the
 * server opens it, the account is on Free and never had a trial, and Pro
 * can honestly be offered on this client and notebook.
 */
export function trialEligible(
  state: ApiBillingState | null,
  notebook: { targetLang: string; meaningLang: string } | undefined,
): boolean {
  return (
    (trialOptInOn() || state?.trialOffered === true) &&
    state !== null &&
    state.plan === 'free' &&
    state.trial === undefined &&
    state.trialEnded === undefined &&
    canBuyHere(state) &&
    cheapestPrice(state) !== undefined &&
    !freeNotebook(state, notebook?.targetLang, notebook?.meaningLang)
  );
}

/**
 * How long a trial started now would run, when the server says
 * (`trialDays`); undefined otherwise, and then nothing names a length.
 */
export function trialDaysOf(state: ApiBillingState | null): number | undefined {
  const days = state?.trialDays;
  return typeof days === 'number' && Number.isInteger(days) && days > 0 ? days : undefined;
}
