/**
 * When the phone apps ask the store for a rating (owner, 2026-10-16). Pure:
 * the caller passes in what it read, and gets back yes or the reason for no.
 * Every threshold is a named constant here with a test (`rules.test.ts`).
 *
 * THE RULE THAT MAKES THIS LEGAL, and that no change may bend:
 * we choose only WHEN to hand the moment to the store, from what the learner
 * just did in the app. We never ask the learner anything first. No "Enjoying
 * Lexpad?", no "Rate us 5 stars?", no satisfaction question whose answer
 * decides who sees the store's dialog, no reward for a rating, no custom
 * rating screen, and never a button that opens the dialog.
 * - Google Play, In-App Review API (developer.android.com/guide/playcore/in-app-review,
 *   updated 2026-01-30): "Your app shouldn't ask the user any questions before or while
 *   presenting the rating button or card, including questions about their opinion
 *   (such as 'Do you like the app?') or predictive questions"; no call-to-action
 *   button triggers the API; the card is shown as-is with nothing over it.
 *   Play policy "User Ratings, Reviews, and Installs": no incentives, no forced or
 *   deceptive pop-ups, no manipulation.
 * - Apple, App Review Guideline 5.6.1 (updated 2026-06-08): "Use the provided API to
 *   prompt users to review your app … we will disallow custom review prompts";
 *   3.2.2(x) and Section 3: no forcing, no filtered or incentivized feedback.
 *   StoreKit `requestReview(in:)`: shown at most three times in 365 days; never in
 *   response to a button tap or other user action. HIG "Ratings and reviews": ask
 *   after people have shown engagement, at a natural break, never on first launch,
 *   "at least a week or two between requests".
 * A happy moment below is something the learner DID (a good session, a
 * milestone), never something they SAID about us.
 */
import { WORD_MILESTONES, STREAK_BURST, STREAK_TAKEOVER, crossed } from '@/features/celebrate/moments.js';

// ── The moments worth handing to the store ────────────────────────────────

/** What just went well. */
export type HappyKind = 'session' | 'streak' | 'mastered' | 'words' | 'aiRun';

/**
 * A session counts when it was a real one: at least this many answers…
 * Ten until 26 Oct 2026, which a new learner's notebook almost never gives:
 * half of the accounts hold one to four words, and a day's due cards in a
 * small notebook are fewer than ten, so the prompt had nothing to hand on
 * (growth audit 2026-10-26: no rating on Play after 72 installs). Five is
 * still a run of answers, not a single card.
 */
export const SESSION_MIN_CARDS = 5;
/** …and at least this share of them right. */
export const SESSION_MIN_ACCURACY = 0.8;

/**
 * Streak milestones that count: the celebrated ones from a week up. Three days
 * is too early to have an opinion of the app worth asking for.
 */
export const STREAK_MILESTONES: readonly number[] = [...STREAK_BURST, ...STREAK_TAKEOVER]
  .filter((days) => days >= 7)
  .sort((a, b) => a - b);

/** Words in the notebook that count, the celebrated milestones (the 10th word saved first). */
export const WORDS_MILESTONES: readonly number[] = WORD_MILESTONES;

/** AI-filled cards saved in a row, with no failure, retry or report between them. */
export const AI_RUN_CARDS = 3;

/**
 * A happy moment is handed on at the next calm moment (leaving the summary,
 * closing the add sheet) or not at all: a rating request long after the
 * moment would be an interruption with no reason.
 */
export const HAPPY_FRESH_MS = 10 * 60_000;

// ── Who may be asked ───────────────────────────────────────────────────────

/**
 * Not before the account is this many days old. Both stores say to wait until
 * somebody has used the app enough to have an opinion (Apple HIG: never on
 * first launch or during onboarding; Play: "after a user has experienced enough
 * of your app"). Lexpad's value is words coming back over days, which a first
 * day cannot show. Two, because three days with practice (below) already span
 * at least two whole days; three blocked a learner who practised on the day
 * of sign-up and the two after it.
 */
export const MIN_ACCOUNT_DAYS = 2;

/** And not before the learner has practised on this many different days. */
export const MIN_PRACTICE_DAYS = 3;

/**
 * Days between two requests from this device. Apple shows the dialog at most
 * three times a year and asks for at least a week or two between requests;
 * Google's quota is undisclosed and says a second call within "less than a
 * month" may show nothing. Sixty days keeps every call one the stores will
 * honour. Ninety since 26 Oct 2026 (owner: at most once in 90 days).
 */
export const COOLDOWN_DAYS = 90;

/** The store's own ceiling, Apple's: three in any 365 days. We stop there too. */
export const MAX_ASKS_PER_YEAR = 3;
export const YEAR_DAYS = 365;

/**
 * Asks kept in the ledger: enough to apply the yearly ceiling. Fixed by the
 * ceiling above, not data.
 */
export const ASKS_KEPT = MAX_ASKS_PER_YEAR;

/**
 * The server's kill switch: an `srs_v2` feature, on unless the server sends it
 * false (like `celebrations`), so it needs no SRS v2 rollout. It only exists in
 * the shells; the web, the desktop app and the extension never ask.
 */
export const REVIEW_FEATURE = 'storeReview';

const DAY_MS = 86_400_000;

// ── This device's ledger ───────────────────────────────────────────────────

/** What this device remembers, in `platform.prefs` so it survives signing out. */
export interface ReviewLedger {
  /** When the store was asked, oldest first, as UTC ISO strings. */
  asks: string[];
  /** App versions that already asked, so one version never asks twice. */
  versions: string[];
  /** The local day the learner reported something or hit an error; none that day. */
  troubleDay: number | null;
  /** AI-filled cards saved in a row so far. */
  aiRun: number;
}

export const EMPTY_LEDGER: ReviewLedger = { asks: [], versions: [], troubleDay: null, aiRun: 0 };

/** Reads a stored ledger, dropping anything malformed rather than failing. */
export function parseLedger(raw: string | null): ReviewLedger {
  if (raw === null) return EMPTY_LEDGER;
  try {
    const value = JSON.parse(raw) as Partial<ReviewLedger> | null;
    if (value === null || typeof value !== 'object') return EMPTY_LEDGER;
    const asks = Array.isArray(value.asks)
      ? value.asks.filter((at): at is string => typeof at === 'string' && !Number.isNaN(Date.parse(at)))
      : [];
    const versions = Array.isArray(value.versions)
      ? value.versions.filter((v): v is string => typeof v === 'string')
      : [];
    const troubleDay = typeof value.troubleDay === 'number' ? value.troubleDay : null;
    const aiRun = typeof value.aiRun === 'number' && value.aiRun >= 0 ? Math.floor(value.aiRun) : 0;
    return { asks, versions, troubleDay, aiRun };
  } catch {
    return EMPTY_LEDGER;
  }
}

/** The ledger after an ask now from this version. */
export function withAsk(ledger: ReviewLedger, now: Date, version: string): ReviewLedger {
  return {
    ...ledger,
    asks: [...ledger.asks, now.toISOString()].slice(-ASKS_KEPT),
    versions: ledger.versions.includes(version) ? ledger.versions : [...ledger.versions, version].slice(-10),
    aiRun: 0,
  };
}

// ── Happy moments, from real events ────────────────────────────────────────

/** What a finished session hands over (`SessionSummary`'s own numbers). */
export interface SessionFacts {
  reviewed: number;
  correct: number;
  /** Words that reached the top box in this session. */
  mastered: number;
  streakBefore: number;
  streak: number;
}

/** The best reason a finished session gives to ask, or undefined. */
export function sessionHappiness(facts: SessionFacts): HappyKind | undefined {
  const accuracy = facts.reviewed === 0 ? 0 : facts.correct / facts.reviewed;
  if (accuracy < SESSION_MIN_ACCURACY) return undefined;
  if (crossed(STREAK_MILESTONES, facts.streakBefore, facts.streak) !== undefined) return 'streak';
  if (facts.mastered > 0) return 'mastered';
  if (facts.reviewed >= SESSION_MIN_CARDS) return 'session';
  return undefined;
}

/** Whether a save that took the account from `before` to `after` words crossed a milestone. */
export function wordsHappiness(before: number, after: number): HappyKind | undefined {
  return crossed(WORDS_MILESTONES, before, after) === undefined ? undefined : 'words';
}

/** One AI-filled card's fate in the add sheet. */
export type AiOutcome = 'saved' | 'failed' | 'retried';

/** The run after one more AI card, and whether it just became a happy moment. */
export function nextAiRun(run: number, outcome: AiOutcome): { run: number; happy: boolean } {
  if (outcome !== 'saved') return { run: 0, happy: false };
  const next = run + 1;
  return next >= AI_RUN_CARDS ? { run: 0, happy: true } : { run: next, happy: false };
}

// ── The decision ───────────────────────────────────────────────────────────

/** Everything the decision reads. */
export interface Gate {
  now: Date;
  /** Today's local day index. */
  today: number;
  ledger: ReviewLedger;
  /** `platform.env.platform`: only 'ios' and 'android' ever ask. */
  platform: string;
  /** Whether the host has the store's dialog at all (`platform.review`). */
  hasStore: boolean;
  appVersion: string;
  /** The server's switch (`REVIEW_FEATURE`), already read. */
  switchOn: boolean;
  /** The account's creation, UTC ISO. Unknown is too young. */
  accountCreatedAt: string | undefined;
  /** Different days with practice in this account. */
  practiceDays: number;
  online: boolean;
  /** The last happy moment and when it happened (ms since epoch). */
  happy: { kind: HappyKind; at: number } | undefined;
  /**
   * Whether a selling surface was on screen in this app session: a paywall,
   * an offer sheet or banner, the Plan page's prices, the store's purchase
   * sheet (`billing/sellingSignals.ts`). A rating is never asked for in the
   * same session (marketing 2026-10-16 study §8). The session ends after
   * `SELLING_SESSION_MS` (`review.ts`); a phone app stays in memory for days,
   * and "this run" used to mean a banner seen on Monday silenced Thursday.
   */
  sellingShown: boolean;
  /**
   * Whether the plan is known at all. Money events are read from it, so a
   * plan the server never answered with is not "no money event": it is
   * not knowing, and the prompt waits for another moment.
   */
  planKnown: boolean;
  /**
   * Until when the last money event (a charge, a renewal, the trial's end,
   * Pro lost in this run) keeps the prompt quiet, or undefined (§8).
   */
  moneyQuietUntil: Date | undefined;
}

export type Verdict =
  | { ask: true; kind: HappyKind }
  | {
      ask: false;
      reason:
        | 'platform'
        | 'switch'
        | 'noMoment'
        | 'stale'
        | 'trouble'
        | 'selling'
        | 'money'
        | 'young'
        | 'practice'
        | 'version'
        | 'cooldown'
        | 'yearly'
        | 'offline';
    };

/** Whether to hand this moment to the store now. */
export function decide(gate: Gate): Verdict {
  if (!gate.hasStore || (gate.platform !== 'ios' && gate.platform !== 'android')) {
    return { ask: false, reason: 'platform' };
  }
  if (!gate.switchOn) return { ask: false, reason: 'switch' };
  if (gate.happy === undefined) return { ask: false, reason: 'noMoment' };
  const since = gate.now.getTime() - gate.happy.at;
  if (since < 0 || since > HAPPY_FRESH_MS) return { ask: false, reason: 'stale' };
  if (gate.ledger.troubleDay === gate.today) return { ask: false, reason: 'trouble' };
  if (gate.sellingShown) return { ask: false, reason: 'selling' };
  if (!gate.planKnown) return { ask: false, reason: 'money' };
  if (gate.moneyQuietUntil !== undefined && gate.moneyQuietUntil.getTime() > gate.now.getTime()) {
    return { ask: false, reason: 'money' };
  }
  const created = gate.accountCreatedAt === undefined ? Number.NaN : Date.parse(gate.accountCreatedAt);
  if (Number.isNaN(created) || gate.now.getTime() - created < MIN_ACCOUNT_DAYS * DAY_MS) {
    return { ask: false, reason: 'young' };
  }
  if (gate.practiceDays < MIN_PRACTICE_DAYS) return { ask: false, reason: 'practice' };
  if (gate.ledger.versions.includes(gate.appVersion)) return { ask: false, reason: 'version' };
  const asks = gate.ledger.asks.map((at) => Date.parse(at)).filter((at) => !Number.isNaN(at));
  const last = asks.length === 0 ? undefined : Math.max(...asks);
  if (last !== undefined && gate.now.getTime() - last < COOLDOWN_DAYS * DAY_MS) {
    return { ask: false, reason: 'cooldown' };
  }
  const inYear = asks.filter((at) => gate.now.getTime() - at < YEAR_DAYS * DAY_MS).length;
  if (inYear >= MAX_ASKS_PER_YEAR) return { ask: false, reason: 'yearly' };
  if (!gate.online) return { ask: false, reason: 'offline' };
  return { ask: true, kind: gate.happy.kind };
}
