/**
 * Which celebration, if any, a screen shows (uiux/2026-10-09-delight-and-intro.md
 * §B). Pure: the screen passes in what just happened and the keys already
 * spent, and gets back at most one moment (and, under a big one, one line).
 *
 * Every moment has a **key** that says what makes it once: `first-session`,
 * `streak:<run start>:7`, `words:100`, `alldone:<day>`… A key is spent when it
 * is shown, or when it was true and lost to a higher one (a late celebration
 * feels fake, so nothing is kept for a later day). Spent keys are claimed on
 * the server (`POST /me/celebrations/claim`), which hands each key to one
 * device only, so a milestone is never celebrated twice across the web, the
 * phone apps and the desktop app.
 *
 * Every cap below is a named constant with a test (`moments.test.ts`).
 */

/** The moments, in the design's rank order (1 is the most important). */
export const MOMENT_IDS = [
  'firstSession',
  'firstRecall',
  'streak3',
  'streak7',
  'firstMastered',
  'allDone',
  'words',
  'comeback',
  'streakMid',
  'streakBig',
  'mastered',
  'streakBest',
  'freezeSaved',
  'slipBeaten',
  'busiest',
  'trialStart',
  'anniversary',
] as const;

export type MomentId = (typeof MOMENT_IDS)[number];

/** Rank: lower wins when two compete on one screen. */
export const RANK: Readonly<Record<MomentId, number>> = Object.fromEntries(
  MOMENT_IDS.map((id, index) => [id, index + 1]),
) as Record<MomentId, number>;

/**
 * How big a moment is. A line is one sentence in the screen; a toast is a
 * line at the foot of the screen (the add sheet has closed); a burst is the
 * summary's head turning into the moment, with confetti; a takeover is the
 * Pro-style sheet.
 */
export type MomentSize = 'line' | 'toast' | 'burst' | 'takeover';

/** Where a moment may appear. Never in a card, the add sheet, Lex, the reader or Settings. */
export type MomentPlace = 'summary' | 'today' | 'notebook';

/** A word a moment names, with the notebook that says its language. */
export interface MomentWord {
  id: string;
  headword: string;
  notebookId: string;
}

/** One moment, ready to draw. Every number in it is the learner's own. */
export interface Moment {
  id: MomentId;
  /** What makes it once; claimed on the server when it is spent. */
  key: string;
  size: MomentSize;
  /** A milestone value: days in a row, words, words mastered, cards, years. */
  count?: number;
  /** The previous best, for the longest streak. */
  previous?: number;
  /** Days: since a word was last seen, or until the next check of a mastered word. */
  days?: number;
  box?: number;
  word?: MomentWord;
  /** The first session's line: one word moved up, missed, or several words. */
  variant?: 'right' | 'missed' | 'many' | 'manyLater';
  /** The trial's end, as the server sent it. */
  endsAt?: string;
  /** A day index: the day a freeze covered. */
  day?: number;
}

/** What a screen shows: one moment, a line under it when the moment is big, and every key it spent. */
export interface Pick {
  main?: Moment;
  extra?: Moment;
  /** Keys spent by this pick, shown or not; `big:<day>` too when the main moment is big. */
  spent: string[];
}

export const NOTHING: Pick = { spent: [] };

// ── Caps ───────────────────────────────────────────────────────────────────

/** Big moments (a burst or a takeover) per local day, across every device of the account. */
export const BIG_PER_DAY = 1;

/** In an account's first hours only the first session is celebrated; the first day is add, practise, come back. */
export const QUIET_HOURS = 24;

/** The only moments allowed in those first hours. */
export const FIRST_HOURS_MOMENTS: ReadonlySet<MomentId> = new Set<MomentId>(['firstSession']);

/**
 * Moments that stay true later and are not a crossing: held back by a cap,
 * they wait for the next time rather than being spent. "You remembered X
 * after N days" describes the session it is in, so it is never late.
 */
export const WAITS_WHEN_CAPPED: ReadonlySet<MomentId> = new Set<MomentId>(['firstRecall']);

/** Days in a row that are celebrated, and how. Every `STREAK_YEAR` after a year is a takeover too. */
export const STREAK_LINE = [3] as const;
export const STREAK_BURST = [7, 14, 50, 200] as const;
export const STREAK_TAKEOVER = [30, 100, 365] as const;
export const STREAK_YEAR = 365;

/** Words in the notebook that are celebrated; the takeovers are the round ones. */
export const WORD_MILESTONES = [10, 50, 100, 250, 500, 1000, 2000, 5000] as const;
export const WORD_TAKEOVERS: ReadonlySet<number> = new Set([100, 500, 1000]);

/** Words in box 5 that are celebrated; from `MASTERED_TAKEOVER_FROM` it is a takeover. */
export const MASTERED_MILESTONES = [10, 25, 50, 100, 250, 500, 1000] as const;
export const MASTERED_TAKEOVER_FROM = 100;

/** A longest streak is celebrated only once the old best meant something. */
export const BEST_MIN_PREVIOUS = 5;

/** The busiest day needs a history to beat: days practised before, and a best worth beating. */
export const BUSIEST_MIN_DAYS = 14;
export const BUSIEST_MIN_BEST = 20;

/** Days since the last practice that make a return a "good to have you back". */
export const BREAK_DAYS = 3;

/** Slipping words named one by one; above it the line counts them. */
export const SLIP_NAMED = 1;

/** A frozen day is said only while it is this recent; older, the moment has passed. */
export const FREEZE_RECENT_DAYS = 2;

/** The anniversary is said only to somebody who practised within this many days. */
export const ANNIVERSARY_ACTIVE_DAYS = 30;

// ── Keys ───────────────────────────────────────────────────────────────────

export const keys = {
  firstSession: 'first-session',
  firstRecall: 'first-recall',
  firstMastered: 'first-mastered',
  streak: (runStart: number, value: number): string => `streak:${String(runStart)}:${String(value)}`,
  best: (runStart: number): string => `best:${String(runStart)}`,
  allDone: (day: number): string => `alldone:${String(day)}`,
  busiest: (day: number): string => `busiest:${String(day)}`,
  big: (day: number): string => `big:${String(day)}`,
  words: (value: number): string => `words:${String(value)}`,
  mastered: (value: number): string => `mastered:${String(value)}`,
  comeback: (lastPractised: number): string => `comeback:${String(lastPractised)}`,
  freeze: (day: number): string => `freeze:${String(day)}`,
  slip: (wordId: string): string => `slip:${wordId}`,
  /** By the end's instant in milliseconds: the server's ISO string has colons a key cannot carry. */
  trial: (endsAt: string): string => `trial:${String(Date.parse(endsAt))}`,
  anniversary: (year: number): string => `anniversary:${String(year)}`,
} as const;

/** The first day of the streak that is running today (the streak counts today). */
export function runStart(today: number, streak: number): number {
  return today - Math.max(1, streak) + 1;
}

export function isBig(moment: Moment | undefined): boolean {
  return moment !== undefined && (moment.size === 'burst' || moment.size === 'takeover');
}

/** How a streak value is celebrated, or undefined for a value that is not. */
export function streakSize(value: number): { id: MomentId; size: MomentSize } | undefined {
  if ((STREAK_LINE as readonly number[]).includes(value)) return { id: 'streak3', size: 'line' };
  if (value === 7) return { id: 'streak7', size: 'burst' };
  if ((STREAK_BURST as readonly number[]).includes(value)) return { id: 'streakMid', size: 'burst' };
  if ((STREAK_TAKEOVER as readonly number[]).includes(value) || (value > 0 && value % STREAK_YEAR === 0)) {
    return { id: 'streakBig', size: 'takeover' };
  }
  return undefined;
}

/** Every streak value celebrated up to and including `streak`, for a baseline. */
export function streakValuesUpTo(streak: number): number[] {
  const out: number[] = [];
  for (const value of [...STREAK_LINE, ...STREAK_BURST, ...STREAK_TAKEOVER])
    if (value <= streak) out.push(value);
  for (let year = STREAK_YEAR * 2; year <= streak; year += STREAK_YEAR) out.push(year);
  return out;
}

/** The highest milestone crossed going from `before` to `after` (before < m ≤ after), or undefined. */
export function crossed(milestones: readonly number[], before: number, after: number): number | undefined {
  let best: number | undefined;
  for (const value of milestones) if (before < value && value <= after) best = value;
  return best;
}

/** Every milestone at or below `count`, for a baseline. */
export function reached(milestones: readonly number[], count: number): number[] {
  return milestones.filter((value) => value <= count);
}

/** The size of a words milestone: the round ones take over, the rest are a toast. */
export function wordsSize(value: number): MomentSize {
  return WORD_TAKEOVERS.has(value) ? 'takeover' : 'toast';
}

// ── Choosing ───────────────────────────────────────────────────────────────

/** Rules shared by every place. */
export interface Context {
  today: number;
  /** The account is in its first `QUIET_HOURS`. */
  young: boolean;
  /** Settings → Practice → Celebrations is off on this device. */
  off: boolean;
  /** Keys already spent: on this device, by the baseline, or claimed by another device. */
  spent: ReadonlySet<string>;
  /**
   * A teaching tip has this screen (the summary's leech, mastered or freeze
   * tip). A tip and a celebration line are never on one screen, and on the
   * summary the tip wins: it is once ever and about something the learner
   * acts on. A line is then spent unseen (the recall line waits), and a big
   * moment keeps the tip under it instead of a line.
   */
  tip?: boolean;
}

/**
 * From every moment that is true right now, the one a screen shows. Lower
 * rank wins. A big one becomes a line when today's big moment is already
 * spent. Under a big one, the next moment that is a line already (or the
 * longest streak, which says itself as a line) is shown beneath it; the
 * rest are spent unseen. With celebrations off nothing is shown, and keys
 * are spent so that turning them on does not bring back an old moment.
 */
export function choose(candidates: readonly Moment[], context: Context): Pick {
  const open = candidates.filter((moment) => !context.spent.has(moment.key));
  if (open.length === 0) return NOTHING;
  const ranked = [...open].sort((a, b) => RANK[a.id] - RANK[b.id]);
  if (context.off) return { spent: ranked.map((moment) => moment.key) };

  const allowed = context.young ? ranked.filter((moment) => FIRST_HOURS_MOMENTS.has(moment.id)) : ranked;
  const capped = ranked.filter((moment) => !allowed.includes(moment));
  const spentUnseen = capped.filter((moment) => !WAITS_WHEN_CAPPED.has(moment.id)).map((m) => m.key);

  const [first, ...rest] = allowed;
  if (first === undefined) return { spent: spentUnseen };

  const bigKey = keys.big(context.today);
  const bigUsed = context.spent.has(bigKey);
  const main = isBig(first) && bigUsed ? downgrade(first) : first;
  const extraFrom = isBig(main)
    ? rest.find((moment) => moment.size === 'line' || moment.id === 'streakBest')
    : undefined;
  const extra = extraFrom === undefined ? undefined : { ...extraFrom, size: 'line' as const };
  if (context.tip === true && !isBig(main)) {
    // The tip has the screen: the line is spent unseen, unless it can wait.
    return {
      spent: [
        ...new Set([...allowed, ...capped].filter((m) => !WAITS_WHEN_CAPPED.has(m.id)).map((m) => m.key)),
      ],
    };
  }
  const spent = [...allowed.map((moment) => moment.key), ...spentUnseen];
  if (isBig(main)) spent.push(bigKey);
  const keepExtra = extra !== undefined && context.tip !== true;
  return { main, ...(keepExtra ? { extra } : {}), spent: [...new Set(spent)] };
}

/** A big moment when today's big one is spent: words become a toast, everything else a line. */
export function downgrade(moment: Moment): Moment {
  return { ...moment, size: moment.id === 'words' ? 'toast' : 'line' };
}

/**
 * What the server answered to a claim: a main moment it gave to another
 * device is not shown; a big one whose day slot went elsewhere becomes a line.
 */
export function afterClaim(pick: Pick, won: ReadonlySet<string>, today: number): Pick {
  const main = pick.main;
  if (main === undefined) return pick;
  if (!won.has(main.key)) {
    const extra = pick.extra !== undefined && won.has(pick.extra.key) ? pick.extra : undefined;
    return { ...(extra === undefined ? {} : { main: extra }), spent: pick.spent };
  }
  const shownMain = isBig(main) && !won.has(keys.big(today)) ? downgrade(main) : main;
  const extra = pick.extra !== undefined && won.has(pick.extra.key) ? pick.extra : undefined;
  return { main: shownMain, ...(extra === undefined ? {} : { extra }), spent: pick.spent };
}

// ── The summary ────────────────────────────────────────────────────────────

/** One word's move in the session (the summary's own answers). */
export interface MoveSignal {
  word: MomentWord;
  from: number;
  to: number;
  dueDay: number;
  kept: boolean;
}

/** What the session that just ended did, and what the account looked like before it. */
export interface SummarySignals {
  /** Answers in this session. */
  reviewed: number;
  /** No practice before this session, on any day. */
  firstEver: boolean;
  moves: readonly MoveSignal[];
  /** Right answers to words that were due and last answered `days` (≥ 1) days ago. */
  recalls: readonly { word: MomentWord; days: number }[];
  /** Words the leech prompt has flagged that got a right answer while due. */
  slipBeaten: readonly MomentWord[];
  streak: number;
  /** The streak before the session's first answer. */
  streakBefore: number;
  /** The longest streak before the session's first answer. */
  longestBefore: number;
  /** Words that reached box 5 in this session (an undone one is not here). */
  masteredNow: readonly MomentWord[];
  /** Words in box 5 now, across the account. */
  masteredTotal: number;
  /** Due words left today across the account; undefined when not known in time. */
  dueLeft: number | undefined;
  /** Answers in this session to words that were due. */
  dueAnswered: number;
  /** The last day with practice before today. */
  lastPractised: number | undefined;
  /** Cards answered today, this session included. */
  dayReviewed: number;
  /** The busiest day before today, and how many days had practice before today. */
  bestBefore: number;
  practiceDays: number;
  /** The first gap of a mastered word, from core (`MASTERED_STEPS[0]`). */
  masteredDays: number;
}

/** Every summary moment that is true for this session. */
export function summaryCandidates(s: SummarySignals, today: number): Moment[] {
  const out: Moment[] = [];
  if (s.reviewed <= 0) return out;
  const run = runStart(today, s.streak);

  if (s.firstEver) {
    const [only] = s.moves;
    if (s.moves.length === 1 && only !== undefined) {
      out.push(
        only.dueDay <= today
          ? { id: 'firstSession', key: keys.firstSession, size: 'burst', variant: 'missed', word: only.word }
          : {
              id: 'firstSession',
              key: keys.firstSession,
              size: 'burst',
              variant: 'right',
              word: only.word,
              box: only.to,
            },
      );
    } else if (s.moves.length > 1) {
      const soon = s.moves.some((move) => move.dueDay === today + 1);
      out.push({
        id: 'firstSession',
        key: keys.firstSession,
        size: 'burst',
        variant: soon ? 'many' : 'manyLater',
        count: s.moves.length,
      });
    }
  }

  const [recall] = s.recalls;
  if (recall !== undefined) {
    out.push({
      id: 'firstRecall',
      key: keys.firstRecall,
      size: 'line',
      word: recall.word,
      count: recall.days,
    });
  }

  // Only the value this session reached: a streak that grew on another
  // device is not this summary's to celebrate, and a late one feels fake.
  const streakKind = s.streakBefore < s.streak ? streakSize(s.streak) : undefined;
  if (streakKind !== undefined) {
    out.push({ id: streakKind.id, key: keys.streak(run, s.streak), size: streakKind.size, count: s.streak });
  }

  const [mastered] = s.masteredNow;
  if (mastered !== undefined) {
    out.push({
      id: 'firstMastered',
      key: keys.firstMastered,
      size: 'takeover',
      word: mastered,
      days: s.masteredDays,
    });
    const before = s.masteredTotal - s.masteredNow.length;
    const value = crossed(MASTERED_MILESTONES, before, s.masteredTotal);
    if (value !== undefined) {
      out.push({
        id: 'mastered',
        key: keys.mastered(value),
        size: value >= MASTERED_TAKEOVER_FROM ? 'takeover' : 'burst',
        count: value,
      });
    }
  }

  if (s.dueLeft === 0 && s.dueAnswered > 0) {
    out.push({ id: 'allDone', key: keys.allDone(today), size: 'line' });
  }

  if (
    s.lastPractised !== undefined &&
    today - s.lastPractised >= BREAK_DAYS &&
    s.dayReviewed === s.reviewed
  ) {
    out.push({
      id: 'comeback',
      key: keys.comeback(s.lastPractised),
      size: 'line',
      count: s.moves.length,
    });
  }

  if (s.streak > s.longestBefore && s.longestBefore >= BEST_MIN_PREVIOUS && s.streakBefore < s.streak) {
    out.push({
      id: 'streakBest',
      key: keys.best(run),
      size: 'burst',
      count: s.streak,
      previous: s.longestBefore,
    });
  }

  if (s.slipBeaten.length > 0) {
    const [word] = s.slipBeaten;
    out.push({
      id: 'slipBeaten',
      // The first of them names the moment; each word is its own key below.
      key: keys.slip(word?.id ?? ''),
      size: 'line',
      count: s.slipBeaten.length,
      ...(s.slipBeaten.length <= SLIP_NAMED && word !== undefined ? { word } : {}),
    });
  }

  if (
    s.practiceDays >= BUSIEST_MIN_DAYS &&
    s.bestBefore >= BUSIEST_MIN_BEST &&
    s.dayReviewed > s.bestBefore &&
    s.dayReviewed - s.reviewed <= s.bestBefore
  ) {
    out.push({ id: 'busiest', key: keys.busiest(today), size: 'line', count: s.dayReviewed });
  }
  return out;
}

/** The summary's moment. Slipping words beyond the first are spent with it. */
export function pickSummary(s: SummarySignals, context: Context): Pick {
  const slipKeys = s.slipBeaten.map((word) => keys.slip(word.id));
  const open = s.slipBeaten.filter((word) => !context.spent.has(keys.slip(word.id)));
  const signals: SummarySignals = { ...s, slipBeaten: open };
  const pick = choose(summaryCandidates(signals, context.today), context);
  const slipShown = pick.spent.some((key) => key.startsWith('slip:'));
  return slipShown ? { ...pick, spent: [...new Set([...pick.spent, ...slipKeys])] } : pick;
}

// ── Today ──────────────────────────────────────────────────────────────────

/** What Today knows that can be a moment: things that happened while away. */
export interface TodaySignals {
  /** A words milestone reached by a save today and not shown yet (`pendingWords`). */
  words: number | undefined;
  /** Days a freeze covered, and the streak now. */
  frozenDays: readonly number[];
  streak: number;
  /** A running trial that is new to this account, its end as sent, and whether Pro may be spoken of here. */
  trial: { endsAt: string } | undefined;
  /** The account's first word, if its first day was exactly a whole number of years ago today. */
  anniversary: { years: number; year: number; word: MomentWord } | undefined;
  /** The last day with practice, today included. */
  lastPractised: number | undefined;
}

export function todayCandidates(s: TodaySignals, today: number): Moment[] {
  const out: Moment[] = [];
  if (s.words !== undefined) {
    out.push({ id: 'words', key: keys.words(s.words), size: wordsSize(s.words), count: s.words });
  }
  if (s.streak > 0) {
    const recent = s.frozenDays.filter((day) => day < today && today - day <= FREEZE_RECENT_DAYS);
    const day = recent.length === 0 ? undefined : Math.max(...recent);
    if (day !== undefined) {
      out.push({ id: 'freezeSaved', key: keys.freeze(day), size: 'line', day, count: s.streak });
    }
  }
  if (s.trial !== undefined) {
    out.push({ id: 'trialStart', key: keys.trial(s.trial.endsAt), size: 'takeover', endsAt: s.trial.endsAt });
  }
  if (
    s.anniversary !== undefined &&
    s.lastPractised !== undefined &&
    today - s.lastPractised <= ANNIVERSARY_ACTIVE_DAYS
  ) {
    out.push({
      id: 'anniversary',
      key: keys.anniversary(s.anniversary.year),
      size: 'line',
      count: s.anniversary.years,
      word: s.anniversary.word,
    });
  }
  return out;
}

/** Today's moment. Every frozen day already passed is spent with the one shown. */
export function pickToday(s: TodaySignals, context: Context): Pick {
  const pick = choose(todayCandidates(s, context.today), context);
  if (!pick.spent.some((key) => key.startsWith('freeze:'))) return pick;
  const frozen = s.frozenDays.filter((day) => day < context.today).map((day) => keys.freeze(day));
  return { ...pick, spent: [...new Set([...pick.spent, ...frozen])] };
}

/**
 * The notebook, as the add sheet closes: a words milestone that is a toast.
 * A takeover is not drawn over the notebook; it waits for Today, the same day.
 */
export function pickNotebook(words: number | undefined, context: Context): Pick {
  if (words === undefined || wordsSize(words) !== 'toast') return NOTHING;
  return choose([{ id: 'words', key: keys.words(words), size: 'toast', count: words }], context);
}
