/**
 * The store rating request in the phone apps: noting happy moments and
 * trouble as they happen, and handing a fresh happy moment to the store at
 * the next calm point. The rules, and the reason there is never a question of
 * ours in front of the store's dialog, are in `rules.ts`.
 *
 * Calm points are places the learner has just finished something: leaving a
 * session's summary for Today, closing the add or paste sheet on the notebook.
 * Even there the request waits until nothing is open (no sheet, dialog,
 * paywall, takeover or milestone toast) and the screen is Today or the
 * notebook. If that does not happen within a few seconds, this calm point
 * gives up, but the moment stays for the next one until it is
 * `HAPPY_FRESH_MS` old (`decide` says 'stale' then). Before 2026-10-18 a busy
 * screen threw the moment away, so "Add another word" on the summary (which
 * opens the add sheet at once) lost every good session it followed.
 */
import { db, getMeta } from '@/db/schema.js';
import { loadSrsView } from '@/features/schedule/data.js';
import { localDay } from '@/features/celebrate/view.js';
import { platform } from '@/lib/platform/index.js';
import type { ApiBillingState } from '@/api/types.js';
import { useBilling } from '@/features/billing/state.js';
import {
  MONEY_QUIET_DAYS,
  moneyQuietUntil,
  proLostThisSession,
  sellingShownWithin,
} from '@/features/billing/sellingSignals.js';
import { signal } from '@/lib/surface.js';
import {
  decide,
  nextAiRun,
  parseLedger,
  REVIEW_FEATURE,
  sessionHappiness,
  withAsk,
  wordsHappiness,
  type AiOutcome,
  type HappyKind,
  type ReviewLedger,
  type SessionFacts,
  type Verdict,
} from './rules.js';

/** The ledger's key in `platform.prefs` (device bookkeeping, not learner data). */
export const REVIEW_KEY = 'lexpad.review';

const DAY_MS = 86_400_000;

/**
 * How long a selling surface keeps the prompt quiet: one app session, the
 * activity contract's own gap (`SESSION_GAP_MINUTES`, 30). Named here, not
 * imported, so this file does not pull the event sender into its chunk.
 */
export const SELLING_SESSION_MS = 30 * 60_000;

/** How long after a calm point the request waits, so the screen it lands on has drawn. */
export const CALM_DELAY_MS = 1500;
/** How often it looks again while something is open… */
export const CALM_RETRY_MS = 1000;
/** …and how many times before this calm point gives up (the moment itself stays while fresh). */
export const CALM_TRIES = 8;

/** Screens where a request may appear: Today and the notebook's list. */
const CALM_PATHS: ReadonlySet<string> = new Set(['/', '/notebook']);

/** Anything open that a request must never land on. */
const BUSY_SELECTOR =
  '[role="dialog"], [role="alertdialog"], [aria-modal="true"], [role="alert"], [data-moment-toast]';

/** Whether this host can ask at all; everything below is a no-op elsewhere. */
function storeHere(): boolean {
  return (
    platform.review !== undefined && (platform.env.platform === 'ios' || platform.env.platform === 'android')
  );
}

function readLedger(): ReviewLedger {
  return parseLedger(platform.prefs.get(REVIEW_KEY));
}

function writeLedger(ledger: ReviewLedger): void {
  platform.prefs.set(REVIEW_KEY, JSON.stringify(ledger));
}

/** The last happy moment of this run. Kept in memory only: a moment does not outlive the app. */
let happy: { kind: HappyKind; at: number } | undefined;
let timer: ReturnType<typeof setTimeout> | undefined;

function noteHappy(kind: HappyKind): void {
  happy = { kind, at: Date.now() };
}

/** A finished session; the summary is still on screen. */
export function noteSession(facts: SessionFacts): void {
  if (!storeHere()) return;
  const kind = sessionHappiness(facts);
  if (kind !== undefined) noteHappy(kind);
}

/** A save took the account from `before` to `after` words (`trackWords`). */
export function noteWords(before: number, after: number): void {
  if (!storeHere()) return;
  const kind = wordsHappiness(before, after);
  if (kind !== undefined) noteHappy(kind);
}

/** One AI-filled card in the add sheet was saved, failed or asked again. */
export function noteAiCard(outcome: AiOutcome): void {
  if (!storeHere()) return;
  const ledger = readLedger();
  const { run, happy: isHappy } = nextAiRun(ledger.aiRun, outcome);
  if (run !== ledger.aiRun) writeLedger({ ...ledger, aiRun: run });
  if (isHappy) noteHappy('aiRun');
}

/**
 * The learner reported something or hit an error: nothing is asked for the
 * rest of the local day, and a moment already waiting is dropped.
 */
export function noteTrouble(): void {
  if (!storeHere()) return;
  happy = undefined;
  if (timer !== undefined) clearTimeout(timer);
  timer = undefined;
  const ledger = readLedger();
  const today = localDay();
  if (ledger.troubleDay !== today) writeLedger({ ...ledger, troubleDay: today, aiRun: 0 });
}

/** The screen the hash router (shells) or the browser router shows. */
function currentPath(): string {
  const hash = window.location.hash;
  const path = platform.env.embedded && hash.startsWith('#/') ? hash.slice(1) : window.location.pathname;
  const bare = path.split(/[?#]/)[0] ?? '/';
  return bare.length > 1 && bare.endsWith('/') ? bare.slice(0, -1) : bare;
}

/** Nothing is open and the learner is on a screen where a request may land. */
export function calmNow(): boolean {
  return (
    document.visibilityState === 'visible' &&
    CALM_PATHS.has(currentPath()) &&
    document.querySelector(BUSY_SELECTOR) === null
  );
}

async function practiceDays(): Promise<number> {
  return db.dayStats.filter((stat) => stat.reviewed > 0).count();
}

/**
 * The plan, for its money events. Today normally holds it already; when it
 * does not, it is read once, and a plan that still is not known means no ask.
 */
async function knownPlan(): Promise<ApiBillingState | null> {
  const billing = useBilling.getState();
  if (billing.state === null && !billing.loading) await billing.refresh();
  return useBilling.getState().state;
}

/** Reads everything the decision needs and decides. Exported for tests. */
export async function verdictNow(now: Date = new Date()): Promise<Verdict> {
  const [srs, user, days] = await Promise.all([loadSrsView(), getMeta('user'), practiceDays()]);
  // Money first and cheaply: a session that showed a price never reads the plan.
  const sellingShown = sellingShownWithin(SELLING_SESSION_MS, now.getTime());
  const plan = sellingShown ? null : await knownPlan();
  return decide({
    now,
    today: localDay(now),
    ledger: readLedger(),
    platform: platform.env.platform,
    hasStore: platform.review !== undefined,
    appVersion: platform.env.appVersion,
    switchOn: srs.features[REVIEW_FEATURE] !== false,
    accountCreatedAt: user?.createdAt,
    practiceDays: days,
    online: platform.network.online,
    happy,
    sellingShown,
    planKnown: sellingShown || plan !== null,
    // Pro lost in this run (a refund, a card that failed) counts from now.
    moneyQuietUntil: proLostThisSession()
      ? new Date(now.getTime() + MONEY_QUIET_DAYS * DAY_MS)
      : moneyQuietUntil(plan, now),
  });
}

async function attempt(): Promise<void> {
  const verdict = await verdictNow();
  // The operators' count (activity events, admin): every good moment that
  // reached a calm point, asked or held and why. Before 26 Oct 2026 nothing
  // said whether the prompt ever ran, and Play had no rating to show for it.
  if (!verdict.ask) {
    signal({ name: 'review.held', meta: { reason: verdict.reason, kind: happy?.kind ?? 'none' } });
    // A moment that cannot be handed on now never will be: it is not kept.
    happy = undefined;
    return;
  }
  signal({ name: 'review.ask', meta: { kind: verdict.kind } });
  happy = undefined;
  // Written before the call: whatever the store does (shows it, holds it back
  // for its quota, or cannot be reached from a sideloaded APK), this device
  // has used its turn, and a crash inside the call must not repeat it.
  writeLedger(withAsk(readLedger(), new Date(), platform.env.appVersion));
  await platform.review?.request();
}

/**
 * A calm point: the learner has just finished something. If a happy moment is
 * waiting, the store is asked once nothing is open; if something stays open,
 * the moment waits for the next calm point while it is fresh.
 * Never awaits and never throws: the store's answer changes nothing here.
 */
export function askWhenCalm(): void {
  if (!storeHere() || happy === undefined) return;
  if (timer !== undefined) clearTimeout(timer);
  let tries = 0;
  const look = (): void => {
    timer = undefined;
    if (happy === undefined) return;
    if (!calmNow()) {
      tries += 1;
      if (tries < CALM_TRIES) timer = setTimeout(look, CALM_RETRY_MS);
      return;
    }
    attempt().catch((cause: unknown) => {
      // Play refuses an app it did not install; nothing to tell anybody.
      console.warn('store review not shown', cause);
    });
  };
  timer = setTimeout(look, CALM_DELAY_MS);
}

/** Tests only: forget this run's moment and timer. */
export function resetForTests(): void {
  happy = undefined;
  if (timer !== undefined) clearTimeout(timer);
  timer = undefined;
}
