/**
 * What the store-rating prompt must know about money (marketing 2026-10-16
 * study §8, `features/review`): never ask for a rating in a run of the app
 * that showed a paywall, an offer sheet or banner, a store purchase sheet or
 * any plan touch, nor within `MONEY_QUIET_DAYS` after a charge, a renewal,
 * a refund, a failed payment or the end of the trial.
 *
 * This file only keeps the two signals; the review prompt decides with them.
 * Pure but for the one run-wide note, which lives in memory on purpose: "this
 * session" is this run of the app, and a reload starts a new one.
 *
 * - `noteSellingShown()` is called by every selling surface as it appears:
 *   the offer sheet (`Upgrade`), the Plan page with prices, the full-screen
 *   offer, Today's campaign banner and after-milestone cards, the moment
 *   card, the in-feature Pro card, the AI-limit line's price and the store's
 *   own purchase sheet (`purchase.ts`).
 * - `sellingShownThisSession()` answers whether any of them did;
 *   `sellingShownWithin(ms)` whether one did in the last `ms` (the rating
 *   prompt's app session).
 * - `moneyQuietUntil(state)` is when the last money event the plan shows
 *   (a first charge or a renewal, the end of the trial) stops counting, or
 *   undefined when none counts. A failed purchase on this device is the
 *   review prompt's own `noteTrouble` (purchaseProblem.ts).
 * - `notePlanSeen(plan)` / `proLostThisSession()`: the plan does not carry a
 *   refund or a card the store is retrying, so until the server sends them a
 *   plan that went from Pro to Free in this run counts as a money event too.
 *   The billing store reports every plan it holds (`state.ts`).
 */
import type { ApiBillingState } from '@/api/types.js';

/** Days after a money event in which no rating is asked (§8). */
export const MONEY_QUIET_DAYS = 7;

const DAY = 86_400_000;

let shownThisRun = false;
/** When a selling surface was last on screen in this run (ms since epoch). */
let lastShownAt: number | undefined;

/** A selling surface was put on screen in this run of the app. */
export function noteSellingShown(now: number = Date.now()): void {
  shownThisRun = true;
  lastShownAt = now;
}

/** Whether any selling surface was on screen in this run of the app. */
export function sellingShownThisSession(): boolean {
  return shownThisRun;
}

/**
 * Whether a selling surface was on screen in the last `ms`. The rating
 * prompt reads this rather than the whole run: a phone app stays in memory
 * for days, so "this run" kept a banner seen once in front of every good
 * session after it (2026-10-26).
 */
export function sellingShownWithin(ms: number, now: number = Date.now()): boolean {
  return lastShownAt !== undefined && now - lastShownAt < ms;
}

let proSeenThisRun = false;
let proLostThisRun = false;

/**
 * The plan the app now holds for the signed-in account, or undefined when it
 * holds none (signed out, another account): Pro then Free in one run is a
 * money event; a change of account starts over.
 */
export function notePlanSeen(plan: 'free' | 'pro' | undefined): void {
  if (plan === undefined) {
    proSeenThisRun = false;
    return;
  }
  if (plan === 'pro') proSeenThisRun = true;
  else if (proSeenThisRun) proLostThisRun = true;
}

/** Whether the plan went from Pro to Free in this run of the app. */
export function proLostThisSession(): boolean {
  return proLostThisRun;
}

/** For tests: a new run of the app. */
export function forgetSellingShown(): void {
  shownThisRun = false;
  lastShownAt = undefined;
  proSeenThisRun = false;
  proLostThisRun = false;
}

function instant(iso: string | undefined): number | undefined {
  if (iso === undefined) return undefined;
  const ms = Date.parse(iso);
  return Number.isNaN(ms) ? undefined : ms;
}

/**
 * The latest money event the plan shows, as an instant: the paid plan's
 * start or its last renewal (its period's start), or the trial's end.
 * Undefined when there is none.
 */
export function lastMoneyEvent(state: ApiBillingState | null, now: Date): number | undefined {
  if (state === null) return undefined;
  const events: number[] = [];
  const trialEnd = instant(state.trialEnded?.endedAt);
  if (trialEnd !== undefined && trialEnd <= now.getTime()) events.push(trialEnd);
  const sub = state.subscription;
  if (sub !== undefined) {
    const started = instant(sub.startedAt);
    if (started !== undefined) events.push(started);
    // The current period began at the last charge: one period before its end.
    const end = instant(sub.periodEnd);
    if (end !== undefined) {
      const begin = new Date(end);
      if (sub.period === 'year') begin.setFullYear(begin.getFullYear() - 1);
      else begin.setMonth(begin.getMonth() - 1);
      if (begin.getTime() <= now.getTime()) events.push(begin.getTime());
    }
  }
  const latest = events.filter((at) => at <= now.getTime());
  return latest.length === 0 ? undefined : Math.max(...latest);
}

/** Until when money still counts against a rating prompt, or undefined when it does not. */
export function moneyQuietUntil(state: ApiBillingState | null, now: Date): Date | undefined {
  const last = lastMoneyEvent(state, now);
  if (last === undefined) return undefined;
  const until = last + MONEY_QUIET_DAYS * DAY;
  return until > now.getTime() ? new Date(until) : undefined;
}
